package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.DistExecutor;
import net.minecraftforge.network.*;
import net.minecraftforge.network.simple.SimpleChannel;
/** Server-issued sessions validate the current owner, item/station, range and action. */
public final class TycoonNetwork {
    private static final SimpleChannel CHANNEL=NetworkRegistry.newSimpleChannel(ResourceLocation.fromNamespaceAndPath("coraline","tycoon"),()->"1","1"::equals,"1"::equals);
    public record Snapshot(CompoundTag data){}public record Action(UUID nonce,String action,String value){}
    private record Session(UUID nonce,String mode,BlockPos station,UUID child,long expires,UUID owner,UUID epoch){}
    private static Session session(ServerPlayer p,String mode,BlockPos station,UUID child,long ticks){var h=TycoonWorld.home(p);return new Session(UUID.randomUUID(),mode,station,child,p.server.overworld().getGameTime()+ticks,h.owner,h.state.hasUUID("CapabilityEpoch")?h.state.getUUID("CapabilityEpoch"):null);}
    private static final Map<UUID,Session> SESSIONS=new HashMap<>();
    private static final Map<UUID,Long> LAST=new HashMap<>();
    public static void register(){CHANNEL.messageBuilder(Snapshot.class,0,NetworkDirection.PLAY_TO_CLIENT).encoder((m,b)->b.writeNbt(m.data)).decoder(b->new Snapshot(b.readNbt())).consumerMainThread((m,c)->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->com.coraline.client.TycoonScreen.receive(m.data))).add();CHANNEL.messageBuilder(Action.class,1,NetworkDirection.PLAY_TO_SERVER).encoder((m,b)->{b.writeUUID(m.nonce);b.writeUtf(m.action,32);b.writeUtf(m.value,160);}).decoder(b->new Action(b.readUUID(),b.readUtf(32),b.readUtf(160))).consumerMainThread((m,c)->{var p=c.get().getSender();if(p!=null)handle(p,m);}).add();}
    public static void snapshot(ServerPlayer p,CompoundTag n){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new Snapshot(n));}
    public static void visitor(ServerPlayer p,TycoonNpc npc){TycoonScope.run(p,npc.owner,()->visitorOwned(p,npc));}
    private static void visitorOwned(ServerPlayer p,TycoonNpc npc){if(!TycoonWorld.owner(p).equals(npc.owner)||npc.staff()||p.distanceToSqr(npc)>25||TycoonCare.resident(npc)==null||!TycoonCare.resident(npc).n.getCompound("Visit").getString("Phase").equals("INSIDE"))return;var s=session(p,"visitor",null,npc.resident,2400);SESSIONS.put(p.getUUID(),s);send(p,s,"");}
    public static void action(UUID nonce,String action,String value){CHANNEL.sendToServer(new Action(nonce,action,value));}
    public static void open(ServerPlayer p,String mode,BlockPos station){
        boolean debug=Set.of("debug","debug2","fooddebug").contains(mode);if(debug&&!p.hasPermissions(2))return;
        UUID owner=debug?p.getUUID():station!=null&&p.serverLevel().getBlockEntity(station) instanceof TycoonBlockEntity be?be.owner:TycoonWorld.owner(p);
        if(owner!=null&&owner.equals(p.getUUID()))TycoonData.get(p.server).home(owner);
        TycoonScope.run(p,owner,()->openOwned(p,mode,station));
    }
    private static void openOwned(ServerPlayer p,String mode,BlockPos station){if(!Set.of("desk","phone","debug","worlddesk","debug2","fooddebug").contains(mode)||(mode.equals("debug")||mode.equals("debug2")||mode.equals("fooddebug"))&&!p.hasPermissions(2))return;var session=session(p,mode,station,null,12000);if(!valid(p,session))return;SESSIONS.put(p.getUUID(),session);send(p,session,"");}
    public static void child(ServerPlayer p,TycoonNpc npc){TycoonScope.run(p,npc.owner,()->childOwned(p,npc));}
    private static void childOwned(ServerPlayer p,TycoonNpc npc){if(!TycoonWorld.owner(p).equals(npc.owner)||npc.staff()||p.distanceToSqr(npc)>25)return;var s=session(p,"child",null,npc.resident,2400);SESSIONS.put(p.getUUID(),s);send(p,s,"");}
    private static boolean valid(ServerPlayer p,Session s){var home=TycoonData.get(p.server).homes.get(s.owner);if(home==null||!TycoonCollaborators.allowed(p,s.owner)||!s.owner.equals(TycoonWorld.owner(p))||!Objects.equals(s.epoch,home.state.hasUUID("CapabilityEpoch")?home.state.getUUID("CapabilityEpoch"):null))return false;if(!p.isAlive()||p.isSpectator()||p.server.overworld().getGameTime()>s.expires)return false;if(s.mode.equals("debug")||s.mode.equals("debug2")||s.mode.equals("fooddebug"))return p.hasPermissions(2);if(s.mode.equals("desk")||s.mode.equals("worlddesk"))return s.station!=null&&p.distanceToSqr(s.station.getCenter())<=64&&p.serverLevel().getBlockEntity(s.station) instanceof TycoonBlockEntity be&&s.owner.equals(be.owner)&&be.kind().equals("world_work_desk");if(s.mode.equals("phone")){for(var stack:p.getInventory().items)if(TycoonWorld.validPhone(p,stack))return true;return p.serverLevel()==p.server.overworld()&&!p.serverLevel().getEntitiesOfClass(TycoonNpc.class,p.getBoundingBox().inflate(5),a->a.staff()&&s.owner.equals(a.owner)).isEmpty();}if(s.mode.equals("child")||s.mode.equals("visitor")){var h=TycoonWorld.home(p);var r=h.residents.get(s.child);return r!=null&&r.active()&&(!s.mode.equals("visitor")||r.n.getCompound("Visit").getString("Phase").equals("INSIDE"))&&r.n.hasUUID("Entity")&&p.serverLevel().getEntity(r.n.getUUID("Entity")) instanceof TycoonNpc npc&&s.owner.equals(npc.owner)&&p.distanceToSqr(npc)<=25;}return false;}
    private static void handle(ServerPlayer p,Action a){
        var session=SESSIONS.get(p.getUUID());if(session==null||!session.nonce.equals(a.nonce))return;
        TycoonScope.run(p,session.owner,()->handleOwned(p,a));
    }
    private static void handleOwned(ServerPlayer p,Action a){if(com.coraline.postgame.TrueHeartBattle.recoveryPending(p))return;var s=SESSIONS.get(p.getUUID());if(s==null||!s.nonce.equals(a.nonce)||!valid(p,s))return;TycoonTransactions.reconcile(p);TycoonPlacements.reconcile(p);if(TycoonWorld.busy(p)){send(p,s,"A household transaction is waiting for its original player receipt.");return;}long now=p.server.overworld().getGameTime();if(now-LAST.getOrDefault(p.getUUID(),-100L)<4)return;LAST.put(p.getUUID(),now);String result="";try{switch(a.action){case "refresh"->{}case "phone"->{if(s.mode.equals("desk"))result=TycoonShop.phone(p);}case "buy"->{if(s.mode.equals("desk"))result=TycoonShop.buy(p,a.value);}case "inspect"->{if(s.mode.equals("phone"))TycoonAgency.request(p);}case "agency"->{if(s.mode.equals("phone"))TycoonAgency.contact(p);}case "place"->{if(s.mode.equals("phone"))result=TycoonAgency.place(p,UUID.fromString(a.value));}case "child"->{if(s.mode.equals("child"))result=TycoonCare.respond(p,s.child,a.value);}case "phase2"->{if(s.mode.equals("desk")){open(p,"worlddesk",s.station);return;}}case "tycoon2"->{if(s.mode.equals("worlddesk"))result=TycoonPhaseTwoMenus.action(p,a.value);}case "talk"->{if(s.mode.equals("visitor"))result=TycoonPhaseTwoMenus.talk(p,s.child,a.value);}case "fooddebug"->{if(s.mode.equals("fooddebug")&&p.hasPermissions(2))result=TycoonFoodDebug.run(p,a.value);}case "debug2"->{if(s.mode.equals("debug2")&&p.hasPermissions(2))result=TycoonPhaseTwoDebug.run(p,a.value);}case "debug"->{if(s.mode.equals("debug")&&p.hasPermissions(2)){if(a.value.equals("open_food")){open(p,"fooddebug",null);return;}if(a.value.equals("open_phase_two")){open(p,"debug2",null);return;}result=TycoonDebug.run(p,a.value);}}default->{return;}}}catch(IllegalArgumentException invalid){result="Invalid or stale selection.";}send(p,s,result);}
    private static ListTag strings(Collection<String> lines){var list=new ListTag();lines.forEach(s->list.add(StringTag.valueOf(s)));return list;}
    private static void send(ServerPlayer p,Session s,String result){var h=TycoonWorld.home(p);var n=new CompoundTag();n.putUUID("Nonce",s.nonce);n.putString("Mode",s.mode);n.putString("Result",result);n.putInt("VoidPower",TycoonShop.count(p,TycoonContent.VOID_POWER.get()));n.putLong("SoulEssence",h.state.getLong("SoulEssence"));n.putInt("Level",h.level());n.putInt("XP",h.xp());n.putInt("Reputation",h.reputation());n.putLong("Cooldown",h.cooldown());n.putBoolean("PhoneIssued",h.state.getBoolean("PhoneIssued"));n.putBoolean("Activated",h.active());var lines=new ArrayList<String>();lines.add("Owner: "+p.server.getProfileCache().get(h.owner).map(com.mojang.authlib.GameProfile::getName).orElse(h.owner.toString()));n.putUUID("Owner",h.owner);lines.add("World: "+(h.active()?"Woven":"Not activated"));lines.add("Entrance: "+(h.entrance()==null?"Unplaced — world preserved":h.entrance().toShortString()));lines.add("Residents: "+h.activeResidents());lines.add("Placement: "+h.cooldown()/1200+" active minutes remaining");lines.add("Inspection: "+(h.state.getBoolean("Approved")?"Approved":"Approval needed"));if(h.state.contains("InspectionReport"))lines.add(h.state.getString("InspectionReport"));if(h.state.contains("Agency"))lines.add("Agency: "+BlockPos.of(h.state.getLong("Agency")).toShortString());if(h.state.contains("AgencyBlocker"))lines.add(h.state.getString("AgencyBlocker"));n.put("Lines",strings(lines));
        var shop=new ListTag();for(var entry:TycoonConfig.PRICES.entrySet()){var row=new CompoundTag();row.putString("Id",entry.getKey());row.putString("Name",TycoonContent.label(entry.getKey()));row.putInt("Cost",entry.getValue().get());shop.add(row);}n.put("Shop",shop);
        var candidates=new ListTag();for(var child:TycoonAgency.candidates(h)){var c=new CompoundTag();c.putUUID("Id",child.id);c.putString("Name",child.name());c.putInt("Age",child.n.getInt("Age"));c.putInt("Appearance",child.n.getInt("Appearance"));c.putString("Personality",(child.n.getBoolean("OriginalGhostHelper")?"The child who helped you escape the Other World. ":"")+TycoonCare.personality(child));c.putInt("Fee",TycoonAgency.fee(h));candidates.add(c);}n.put("Candidates",candidates);var residents=new ListTag();for(var r:h.residents.values()){var c=new CompoundTag();c.putString("Name",r.name());c.putString("Status",r.n.getString("Status"));c.putString("Task",r.n.getString("Task"));c.putInt("Hunger",(int)r.need("Hunger"));c.putInt("Thirst",(int)r.need("Thirst"));c.putInt("Neglect",(int)r.need("Neglect"));c.putInt("Comfort",r.n.getInt("Comfort"));residents.add(c);}n.put("Residents",residents);
        if(s.child!=null){var child=h.residents.get(s.child);if(child!=null){n.putString("ChildName",child.name());n.putString("Request",child.n.getString("Request"));n.putString("Wanted",child.n.getString("Wanted"));n.putString("Incident",child.n.getString("Incident"));}}
        TycoonPhaseTwoMenus.enrich(p,s.mode,s.child,n);if(s.mode.equals("debug"))n.put("DebugControls",TycoonDebug.controls());if(s.mode.equals("fooddebug"))n.put("DebugControls",TycoonFoodDebug.controls());CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new Snapshot(n));TycoonWorld.dirty(p);
    }
    static boolean managing(ServerPlayer p,UUID owner){var s=SESSIONS.get(p.getUUID());return s!=null&&s.owner.equals(owner)&&TycoonScope.call(p,owner,()->valid(p,s),false);}
    public static void clear(UUID owner){SESSIONS.remove(owner);LAST.remove(owner);}
    public static void clear(){SESSIONS.clear();LAST.clear();}
}
